function dismissLegacyPreloader() {
    const preloader = document.getElementById('preloader');
    if (!preloader || preloader.dataset.dismissed === '1') return;
    preloader.dataset.dismissed = '1';
    preloader.classList.add('hidden');
    window.setTimeout(() => {
        try { preloader.remove(); } catch { }
    }, 700);
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        window.setTimeout(dismissLegacyPreloader, 50);
    }, { once: true });
} else {
    window.setTimeout(dismissLegacyPreloader, 50);
}

window.addEventListener('load', () => {
    window.setTimeout(dismissLegacyPreloader, 0);
}, { once: true });

