function normalizeZipCode(zip) {
    return String(zip || '').replace(/\D/g, '').slice(0, 5);
}

function resolveStateFromZipPrefix(zip) {
    const normalized = normalizeZipCode(zip);
    if (normalized.length < 3) return null;
    const prefix = Number(normalized.slice(0, 3));
    if (!Number.isFinite(prefix)) return null;
    const match = ZIP_STATE_RANGES.find((entry) => entry.ranges.some(([start, end]) => prefix >= start && prefix <= end));
    return match?.state || null;
}

function resolveStateFromZip(zip) {
    const normalized = normalizeZipCode(zip);
    if (normalized.length !== 5) return null;
    const exactState = GROCERY_ZIP_TO_STATE[normalized];
    return exactState || resolveStateFromZipPrefix(normalized);
}

function getRegionalPriceAdjustmentFromZip(zip) {
    const normalized = normalizeZipCode(zip);
    const state = resolveStateFromZip(normalized);
    if (!state) {
        return {
            zipCode: normalized || null,
            state: null,
            adjustmentPercent: 0,
            label: 'National average',
            source: 'national_average'
        };
    }
    const exactZipMatch = Boolean(GROCERY_ZIP_TO_STATE[normalized]);
    const statePricing = GROCERY_STATE_PRICE_ADJUSTMENTS[state];
    const adjustmentPercent = Number(statePricing?.adjustmentPercent || 0);
    const displayAdjustment = Math.abs(adjustmentPercent) < 0.05 ? 0 : adjustmentPercent;
    if (!statePricing) {
        return {
            zipCode: normalized,
            state,
            adjustmentPercent: 0,
            label: `${state} general estimate`,
            source: exactZipMatch ? 'zip_exact_no_price_data' : 'zip_prefix_fallback'
        };
    }
    return {
        zipCode: normalized,
        state,
        stateName: statePricing?.name || state,
        rppIndex: Number(statePricing?.rppIndex || 0),
        relativeMultiplier: Number(statePricing?.relativeMultiplier || 1),
        adjustmentPercent: displayAdjustment,
        label: displayAdjustment === 0
            ? `${state} baseline`
            : `${state} estimate (${displayAdjustment > 0 ? '+' : ''}${displayAdjustment.toFixed(1)}%)`,
        source: exactZipMatch ? 'zip_exact_bea_2024' : 'zip_prefix_fallback'
    };
}

